<template>
    <div class="calendar-container" v-click-outside="close">
        <div class="">
            <input
                title=""
                :placeholder="placeholder"
                :class="inputClass"
                class="calendar-input"
                v-model="inputValue"
                readonly="readonly"
                :disabled="disabled"
                @focus="open"
                @blur="close"
                @mousedown.prevent="focus"
                ref="input"
            />
        </div>
        <div class="calendar-dropdown simple-dropdown" v-if="isShowCalendar" @mousedown.prevent="">
            <div class="date-picker-container" v-if="!isDateSelected">
                <div class="action-buttons" v-if="isShowActionButtons">
                    <div class="month-changer prev-month"
                         :class="{'disabled': !checkAllowPrev()}"
                         @click="prevMonthView"
                    >
                        <slot name="previousSign">
                            <i class="fa fa-chevron-left"></i>
                        </slot>
                    </div>
                    <div class="month-changer next-month"
                         :class="{'disabled': !checkAllowNext()}"
                         @click="nextMonthView"
                    >
                        <slot name="nextSign">
                            <i class="fa fa-chevron-right"></i>
                        </slot>
                    </div>
                </div>
                <slot name="title" v-if="title">
                    <div class="title">{{ title }}</div>
                </slot>
                <div class="layer-container">
                    <calendar-layer v-for="(layer, index) in activeLayers"
                        :key="index"
                        :min="limitMin"
                        :current="dateModel"
                        :max="limitMax"
                        :month="layer.month"
                        :year="layer.year"
                        :marked-range="markedDateRange"
                        :disabled-days="disabledDays"
                        :locale="normalizedLocale"
                        :value="dateModel"
                        :model-value="dateModel"
                        @input="dateModel = $event"
                        @update:modelValue="dateModel = $event"
                        @select="selectHandler"
                        @dayHover="payload => $emit('dayHover', payload)"
                        @layer="payload => selectLayer(payload, index)"
                    >
                        <template v-slot:day="params">
                            <slot name="day" :day="params.day" />
                        </template>
                    </calendar-layer>
                </div>
            </div>
            <div class="time-picker-container" v-else-if="!isTimeSelected">
                <time-picker
                             :value="dateModel"
                             :model-value="dateModel"
                             :format="format"
                             :min="limitMin"
                             :max="limitMax"
                             @input="dateModel = $event"
                             @update:modelValue="dateModel = $event"
                             @close="selectHandler(true)"
                >
                    <template #title>
                        <slot name="time-title" v-if="timeTitle">
                            <span class="title" v-text="timeTitle"></span>
                        </slot>
                    </template>
                </time-picker>
            </div>
        </div>
    </div>
</template>

<script>
import ClickOutsideDirective from '@ttbooking/vue-click-outside-directive';
import CalendarLayer from "./CalendarLayer.vue";
import TimePicker from "./TimePicker.vue";
import dayjs from '../setup.dayjs.js';

export default {
    components: {TimePicker, CalendarLayer},
    name: "vue-calendar",
    props: {
        value: String,
        modelValue: String,
        placeholder: String,
        format: {
            type: String,
            default: 'DD.MM.YYYY'
        },
        calendarsCount: {
            type: Number,
            default: 1,
        },
        inputClass: {
            type: [Object, String],
            default() {
                return 'form-control'
            }
        },
        min: {
            type: String,
            default: null
        },
        max: {
            type: String,
            default: null
        },
        markedRange: {
            type: Array,
            default() {
                return []
            }
        },
        title: {
            type: String,
            default: null,
        },
        timeTitle: {
            type: String,
            default: null,
        },
        disabledDays: {
            type: Function,
            default: null,
        },
        disabled: {
            type: Boolean,
            default: false,
        },
        locale: {
            type: [String, Object],
            default: () => {
                const locale = typeof window !== 'undefined'
                    ? window.locale && window.locale.toLowerCase()
                    : null;
                return locale ? locale.split('-')[0] : 'ru';
            },
        }
    },
    emits: ['input', 'update:modelValue', 'dayHover', 'selected', 'layerChange', 'focus', 'close'],
    created() {
        this.initCalendar();
    },
    data() {
        const initialValue = this.modelValue !== undefined ? this.modelValue : this.value;
        return {
            inputValue: initialValue,
            dateModel: this.getDateModelFromValue(initialValue),
            activeLayers: [],
            isDateSelected: true,
            isTimeSelected: true,
        };
    },
    computed: {
        currentValue() {
            return this.modelValue !== undefined ? this.modelValue : this.value;
        },
        isWithTime() {
            return this.format.match(/[Hhkms]/)
        },
        isShowCalendar() {
            return !(this.isTimeSelected && this.isDateSelected);
        },
        normalizedLocale() {
            return this.getNormalizedLocale();
        },
        markedDateRange() {
            let range = [];
            if (this.markedRange && this.markedRange.length) {
                for (let i in this.markedRange) {

                    range.push({
                        start: this.parseDate(this.markedRange[i].period.start).startOf('day'),
                        end: this.parseDate(this.markedRange[i].period.end).endOf('day'),
                        class: this.markedRange[i].class,
                    })

                }
            }
            return range;
        },
        limitMin() {
            return this.parseDate(this.min);
        },
        limitMax() {
            return this.parseDate(this.max);
        },
        isShowActionButtons() {
            return this.checkAllowPrev() || this.checkAllowNext();
        }
    },
    methods: {
        syncInputValue(value) {
            if (this.inputValue !== value) {
                this.inputValue = value;
                this.dateModel = this.getDateModelFromValue();
            }
        },
        isBefore(date, limit) {
            return date.isValid() && limit.isValid() && date.valueOf() < limit.valueOf();
        },
        isAfter(date, limit) {
            return date.isValid() && limit.isValid() && date.valueOf() > limit.valueOf();
        },
        normalizeLocale(locale) {
            return String(locale || 'ru').toLowerCase().split(/[-_]/)[0] || 'ru';
        },
        getNormalizedLocale() {
            if (typeof this.locale === 'string') {
                return this.normalizeLocale(this.locale);
            }
            if (this.locale && typeof this.locale === 'object') {
                return this.normalizeLocale(
                    this.locale.locale || this.locale.lang || this.locale.code || this.locale.name
                );
            }
            return 'ru';
        },
        parseDate(value) {
            const locale = this.getNormalizedLocale();
            return dayjs(value, this.format, locale).locale(locale);
        },
        getLocalizedDate() {
            return dayjs().locale(this.getNormalizedLocale());
        },
        initCalendarLayers(date) {
            if (date && date.isValid()) {
                let dateClone = date.endOf('month');

                if (this.limitMin.diff(dateClone, 'month') > 0) {
                    dateClone = dateClone.month(this.limitMin.month())
                        .year(this.limitMin.year())
                    ;
                }

                this.activeLayers = [];
                for (let i = 0; i < this.calendarsCount; i++) {
                    this.activeLayers.push({
                        month: dateClone.month(),
                        year: dateClone.year(),
                        moment: dateClone,
                    });
                    dateClone = dateClone.add(1, 'month');
                }
            }
        },
        initCalendar() {
            let date = this.dateModel && this.dateModel.isValid() ? this.dateModel : this.getLocalizedDate();

            if (this.min && this.min.length && this.isBefore(date, this.limitMin)) {
                this.inputValue = this.min;
                this.dateModel = this.limitMin;
                date = this.limitMin;
            }
            if (this.max && this.max.length && this.isAfter(date, this.limitMax)) {
                if (!this.limitMin.isValid() || this.isAfter(this.limitMax, this.limitMin)) {
                    this.inputValue = this.max;
                    this.dateModel = this.limitMax;
                    date = this.limitMax;
                }
            }

            this.initCalendarLayers(date);
        },
        getDateModelFromValue(value = this.currentValue) {
            return this.parseDate(value);
        },
        focus() {
            setTimeout(() => {
                this.$refs.input.focus();
                this.$emit('focus', this.activeLayers);
            })
        },
        blur() {
            // Keep focus transitions async so click handlers inside the picker can finish first.
            setTimeout(() => {
                this.$refs.input.blur();
            });
        },
        open() {
            this.isDateSelected = false;
            this.isTimeSelected = !this.isWithTime;
        },
        close() {
            if (this.isShowCalendar) {
                // Если дату установили, при этом время не установлено, тогда бросим событие
                // Иначе если дату не установили, то и события быть не должно
                let selected = this.isDateSelected && !this.isTimeSelected && this.isWithTime;

                this.isDateSelected = true;
                this.isTimeSelected = true;
                this.$emit('close', this.activeLayers);

                if (selected) {
                    this.$emit('selected', this.activeLayers);
                }

            }
        },
        toggle() {
            this.isShowCalendar ? this.close() : this.open();
        },
        checkAllowPrev() {
            if (!this.activeLayers.length) {
                return false;
            }
            if (this.limitMin.isValid()) {
                let firstMonth = this.activeLayers[0].moment;
                firstMonth = firstMonth.subtract(1, 'month').endOf('month');
                return !this.isBefore(firstMonth, this.limitMin);
            }
            return true;
        },
        checkAllowNext() {
            if (!this.activeLayers.length) {
                return false;
            }
            if (this.limitMax.isValid()) {
                let lastMonth = this.activeLayers[this.activeLayers.length - 1].moment;
                lastMonth = lastMonth.add(1, 'month').startOf('month');
                return !this.isBefore(this.limitMax, lastMonth);
            }
            return true;
        },
        prevMonthView() {
            if (this.checkAllowPrev()) {
                let firstMonth = this.activeLayers[0].moment;
                firstMonth = firstMonth.subtract(1, 'month');
                this.initCalendarLayers(firstMonth);
                this.$emit('layerChange', this.activeLayers)
            }
        },
        nextMonthView() {
            if (this.checkAllowNext()) {
                let lastMonth = this.activeLayers[0].moment;
                lastMonth = lastMonth.add(1, 'month'); //перескакиваем, плавно по одному месяцу
                this.initCalendarLayers(lastMonth);
                this.$emit('layerChange', this.activeLayers)
            }
        },
        selectHandler(isTime = false) {
            if (isTime) {
                this.blur();
            } else {
                this.isDateSelected = true;
                if (!this.isWithTime) {
                    this.$emit('selected', this.activeLayers);
                    this.blur();
                }
            }
        },
        getActiveLayers() {
            return this.activeLayers;
        },
        setActiveLayers(layers) {
            this.$nextTick(() => this.activeLayers = layers);
        },
        selectLayer(payload, index) {
            let date = this.activeLayers[index].moment.set(payload.key, payload.value).subtract(index, "month");
            this.initCalendarLayers(date);
            this.$emit('layerChange', this.activeLayers)
        }
    },
    watch: {
        min() {
            this.initCalendar();
        },
        max() {
            this.initCalendar();
        },
        locale() {
            this.dateModel = this.getDateModelFromValue();
            this.initCalendar();
        },
        value: {
            handler() {
                this.syncInputValue(this.currentValue);
            },
            immediate: true,
        },
        modelValue: {
            handler() {
                this.syncInputValue(this.currentValue);
            },
            immediate: true,
        },
        inputValue(value) {
            this.$emit('input', value);
            this.$emit('update:modelValue', value);
        },
        dateModel() {
            if (this.dateModel.isValid()) {

                if (this.limitMin && this.limitMin.isValid() && this.isBefore(this.dateModel, this.limitMin)) {
                    this.dateModel = this.limitMin;
                }
                if (this.limitMax && this.limitMax.isValid() && this.isAfter(this.dateModel, this.limitMax)) {
                    this.dateModel = this.limitMax;
                }

                let formattedDate = this.dateModel.format(this.format);
                if (formattedDate !== this.inputValue) {
                    this.inputValue = formattedDate;
                }
            } else if (this.inputValue) {
                this.inputValue = '';
            }

        }
    },
    directives: {
        'click-outside': ClickOutsideDirective,
    }
}
</script>
